{
  "table": {
    "name": "satscores",
    "purpose": "California school/district-level SAT exam results: enrollment of grade-12/graduates, test takers, and average SAT section scores (reading/critical reading, math, writing) plus number meeting benchmark, by school or district."
  },
  "columns": {
    "col_001": {
      "role": "identifier",
      "name": "cds_code",
      "description": "Primary key. 14-digit CDS (County-District-School) code identifying the school (S rows) or district (D rows) the record reports on.",
      "status": "resolved"
    },
    "col_002": {
      "role": "code",
      "name": "record_type",
      "description": "Reporting level: 'S' = school-level record (has school name), 'D' = district-level record (school name null).",
      "status": "resolved"
    },
    "col_003": {
      "role": "category",
      "name": "school_name",
      "description": "School name; null for district-level (D) records.",
      "status": "resolved"
    },
    "col_004": {
      "role": "category",
      "name": "district_name",
      "description": "District (LEA) name, e.g. 'Los Angeles Unified'.",
      "status": "resolved"
    },
    "col_005": {
      "role": "category",
      "name": "county_name",
      "description": "California county name (Los Angeles, San Diego, ...).",
      "status": "resolved"
    },
    "col_006": {
      "role": "numeric",
      "name": "enrollment_grade_12",
      "description": "Number of grade-12 students (enrollment) at the school/district; 0 to 43,324.",
      "status": "tentative"
    },
    "col_007": {
      "role": "numeric",
      "name": "test_takers",
      "description": "Number of students who took the SAT; always <= col_006, 0 to 24,305.",
      "status": "tentative"
    },
    "col_008": {
      "role": "numeric",
      "name": "avg_sat_reading",
      "description": "Average SAT reading/critical reading score (range ~308-653, plausible SAT section scale 200-800). Null when no test takers.",
      "status": "tentative"
    },
    "col_009": {
      "role": "numeric",
      "name": "avg_sat_math",
      "description": "Average SAT math score (range ~289-699, SAT section scale). Null when no test takers.",
      "status": "tentative"
    },
    "col_010": {
      "role": "numeric",
      "name": "avg_sat_writing",
      "description": "Average SAT writing score (range ~312-671, SAT section scale). Null when no test takers.",
      "status": "tentative"
    },
    "col_011": {
      "role": "numeric",
      "name": "num_met_benchmark",
      "description": "Count of students meeting a SAT benchmark/eligibility threshold (0 to 5,837, <= test takers). Exact benchmark definition unresolved.",
      "status": "tentative"
    }
  }
}
